export function highlight(code) {
  const escape = (s) =>
    s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

  const escaped = escape(code);
  const spans = [];
  const protect = (value, pattern, className) =>
    value.replace(pattern, (match) => {
      const marker = String.fromCharCode(0xe100 + spans.length);
      spans.push(`<span class="${className}">${match}</span>`);
      return marker;
    });

  // Protect complete tokens before applying the remaining rules. Otherwise
  // later regexes parse the markup generated by earlier ones.
  let highlighted = protect(escaped, /#[^\n]*/g, "hl-c");
  highlighted = protect(highlighted, /("[^"\\]*(?:\\.[^"\\]*)*")/g, "hl-s");
  highlighted = highlighted.replace(
    /\b(import|from|as|def|return|class|with|if|else|elif|while|for|in|None|True|False|and|or|not)\b/g,
    '<span class="hl-k">$1</span>'
  );
  highlighted = highlighted.replace(/\b(\d+\.?\d*(?:e-?\d+)?)\b/g, '<span class="hl-n">$1</span>');
  highlighted = highlighted.replace(
    /\b(Kernos|Buffer|GridSearchCV)\b/g,
    '<span class="hl-t">$1</span>'
  );
  highlighted = highlighted.replace(
    /\b(X|y|model|search|param_grid|stream|x_batch|y_batch|X_train|y_train|X_test|y_test|seed|steps|dim|mbasis|abasis|lk|ridge|mode|cool|warm|gain|drift_hi|score|fit|predict|partial_fit|standard_normal|default_rng|print|best_params_|best_score_|rng)\b(?=\s*[=,.()\]])/g,
    '<span class="hl-v">$1</span>'
  );

  return highlighted.replace(/[\ue100-\uefff]/g, (marker) => spans[marker.charCodeAt(0) - 0xe100]);
}
